// Simpan ke context global
var data = msg.payload;
data.received = new Date().toISOString();
flow.set('lastSensor', data);

// Simpan history (max 50 data)
var history = flow.get('history') || [];
history.push(data);
if (history.length > 50) history.shift();
flow.set('history', history);

// Cek batas suhu (threshold)
var maxSuhu = flow.get('maxSuhu');
if (typeof maxSuhu === 'number' && !isNaN(maxSuhu) && data.suhu > maxSuhu) {
    var alertMsg = {
        status: 'alert',
        message: 'Suhu ' + data.suhu + '°C melebihi batas ' + maxSuhu + '°C',
        suhu: data.suhu,
        max_suhu: maxSuhu,
        timestamp: data.received
    };
    flow.set('lastAlert', alertMsg);
    node.warn('NOTIFIKASI SUHU: ' + alertMsg.message);
}

return msg;

const data = flow.get('lastSensor') || { suhu: null, kelembaban: null };

msg.payload = {
    status: 'success',
    data: data,
    server_time: new Date().toISOString()
};

msg.headers = { 'Access-Control-Allow-Origin': '*' };

return msg;

const { DatabaseSync } = global.get('sqlite');
const db = new DatabaseSync('C:/Users/WelcompTC/.node-red/sensor.db');

db.exec(`CREATE TABLE IF NOT EXISTS history (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    suhu REAL,
    kelembaban REAL,
    timestamp TEXT,
    received TEXT
)`);

// Ambil 50 data terakhir, lalu urutkan dari yang terlama
const rows = db.prepare('SELECT suhu, kelembaban, timestamp, received FROM history ORDER BY id DESC LIMIT 50').all();
db.close();
const history = rows.map(r => ({ ...r })).reverse();

msg.payload = {
  status: 'success',
  count: history.length,
  data: history
};
msg.headers = { 'Access-Control-Allow-Origin': '*' };
return msg;

// Cek API key
if (msg.req.headers['x-api-key'] !== 'rahasia123') {
    msg.statusCode = 401;
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    msg.payload = {status: 'error', message: 'API key tidak valid'};
    return [msg, null];
}

var body = msg.payload;
if (!body.device || !body.action) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'device dan action wajib diisi'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return [msg, null];
}

// Publish ke MQTT
var mqttMsg = {payload: body, topic: 'iot/kontrol'};
node.send([null, mqttMsg]);

msg.statusCode = 200;
msg.payload = {
    status: 'success',
    message: 'Perintah terkirim',
    sent: body
};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return [msg, null];

msg.statusCode = 204;
msg.payload = '';
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type'
};
return msg;

// Cek API key
if (msg.req.headers['x-api-key'] !== 'rahasia123') {
    msg.statusCode = 401;
    msg.headers = { 'Access-Control-Allow-Origin': '*' };
    msg.payload = { status: 'error', message: 'API key tidak valid' };
    return msg;
}

var body = msg.payload;
msg.headers = { 'Access-Control-Allow-Origin': '*' };

if (!body || typeof body.max_suhu !== 'number') {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'max_suhu wajib angka' };
    return msg;
}

flow.set('maxSuhu', body.max_suhu);

msg.statusCode = 200;
msg.payload = {
    status: 'success',
    message: 'Threshold diperbarui',
    max_suhu: body.max_suhu
};
return msg;

const { DatabaseSync } = global.get('sqlite');
const db = new DatabaseSync('C:/Users/WelcompTC/.node-red/sensor.db');

db.exec(`CREATE TABLE IF NOT EXISTS history (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    suhu REAL,
    kelembaban REAL,
    timestamp TEXT,
    received TEXT
)`);

const d = msg.payload;
db.prepare('INSERT INTO history (suhu, kelembaban, timestamp, received) VALUES (?, ?, ?, ?)')
  .run(d.suhu, d.kelembaban, d.timestamp, d.received);

db.close();
return null;
